      {
       "id": "eski-2-56",
       "no": 56,
       "text": "Bilgi uçurma konusunu BT bağlamında tartışın.",
       "uncertain": false,
       "uncertainNote": "",
       "type": "open",
       "options": [],
       "answer": null,
       "explanation": "Bilgi uçurma, bir çalışanın işvereninin kamu yararını tehdit eden ihmalkâr, yasa dışı, etik dışı veya tehlikeli bir davranışına dikkat çekmesidir. BT çalışanları sistemlere ve verilere erişimleri nedeniyle güvenlik açıklarını, veri ihlallerini, kusurlu yazılımı veya verilerin kötüye kullanımını fark edebilecek konumdadır. Bilgi uçuran kişi önce gerçekleri doğru şekilde belgelemeli, durumu kurum içinde uygun yollarla bildirmeli, gerekirse dış makamlara başvurmalıdır. Bu süreç kişi için işten çıkarılma, misilleme ve kariyer riski taşır; bazı yasalar ihbarcıları koruma sağlar. Bu nedenle karar dikkatle ve etik bir karar verme süreciyle alınmalıdır."
      },
      {
       "id": "eski-2-57",
       "no": 57,
       "text": "Tarafların özen borcu olup olmadığına mahkemelerin nasıl karar verdiğini açıklayın.",
       "uncertain": false,
       "uncertainNote": "",
       "type": "open",
       "options": [],
       "answer": null,
       "explanation": "Özen borcu, başkalarını makul olmayan zarar veya riskten koruma yükümlülüğüdür. Mahkemeler bunu belirlerken \"makul kişi standardı\"nı kullanır: dikkatli, objektif ve makul bir kişinin aynı durumda nasıl davranacağına bakılır. Uzmanlık gerektiren işlerde ise \"makul profesyonel standardı\" uygulanır: o alandaki makul bir profesyonelin nasıl davranacağı esas alınır. Taraf bu standarda göre davranmamışsa özen borcunu ihlal etmiş (ihmal) sayılır. BT çalışanları yasal anlamda \"profesyonel\" kabul edilmediğinden, mahkemeler genellikle onları mesleki hatadan (malpractice) sorumlu tutmamıştır; ancak ihmalden sorumlu tutulabilirler."
      },
      {
       "id": "eski-2-58",
       "no": 58,
       "text": "Mesleki etik kuralları nedir?",
       "uncertain": false,
       "uncertainNote": "",
       "type": "open",
       "options": [],
       "answer": null,
       "explanation": "Mesleki etik kuralları, belirli bir meslek grubunun çalışması için gerekli olan ilkeleri ve temel değerleri belirten kurallardır. Genellikle iki bölümden oluşur: (1) meslek grubunun özlemlerini/ideallerini anlatan temel ilkeler, (2) beklenen davranışları tanımlayan kurallar. Faydaları: etik karar vermede rehberlik eder, yüksek davranış standartlarını destekler, kamuoyunun güvenini ve saygısını artırır, değerlendirme için bir ölçüt oluşturur. Örnek: ACM, IEEE-CS, AITP gibi kuruluşların etik kuralları."
      },
      {
       "id": "eski-2-59",
       "no": 59,
       "text": "Çıkar çatışması terimini tanımlayın ve buna BT ile ilgili bir örnek verin.",
       "uncertain": false,
       "uncertainNote": "",
       "type": "open",
       "options": [],
       "answer": null,
       "explanation": "Çıkar çatışması, bir kişinin kendi (veya yakınlarının) kişisel çıkarının, işvereninin veya müşterisinin çıkarına hizmet etme yükümlülüğüyle çeliştiği durumdur. BT örneği: Bir BT danışmanının müşterisinin sistemini denetleyip tespit ettiği sorunu çözmek için kendi şirketinin veya ortaklık ilişkisi olduğu bir satıcının ürününü tavsiye etmesi. Ayrıca bir BT yöneticisinin, kendisine hediye veren veya akrabasının çalıştığı bir tedarikçiyi seçmesi de çıkar çatışmasıdır."
      },
      {
       "id": "eski-2-60",
       "no": 60,
       "text": "Bir kuruluşun denetim komitesi ile iç denetim departmanı arasındaki farkı açıklığa kavuşturun.",
       "uncertain": false,
       "uncertainNote": "",
       "type": "open",
       "options": [],
       "answer": null,
       "explanation": "- Denetim komitesi: Yönetim kurulu üyelerinden oluşur (bağımsız üyeler). Mali raporlama sürecinin kalitesini ve bütünlüğünü, dış denetçilerin bağımsızlığını, yasal düzenlemelere uyumu ve iç denetim çalışmalarını gözetir. Yani üst düzey gözetim organıdır.\n- İç denetim departmanı: Kurum çalışanlarından oluşan bir birimdir. İç sistem ve kontrollerin yeterli ve etkili olup olmadığını inceler, mevzuata ve politikalara uyumu kontrol eder, mali tablo sahtekârlığını tespit eder ve soruşturur. Bulgularını denetim komitesine raporlar."
      }
