       "no": 21,
       "text": "Kuruluşlar, kilit çalışanlar ayrıldığında ticari sırları kaybetme riskiyle karşı karşıya kalabileceğinden, genellikle iş sözleşmelerine rekabet etmeme hükümleri ekleyerek çalışanların sırları ifşa etmesini yasaklamaya çalışırlar.",
