       "no": 2,
       "text": "Bir sosyal ağ platformu, üyelerin zaman, mesafe ve kültürel farklılıkların yarattığı engelleri yıkmalarını sağlayan çevrimiçi bir İnternet kullanıcıları topluluğu oluşturur.",
